def find_median_sorted_arrays(a, b):
    m = n = 0; merge = []
    while m < len(a) and n < len(b):
        if a[m] < b[n]: merge.append(a[m]); m += 1
        else: merge.append(b[n]); n += 1
    merge += a[m:] + b[n:]
    L = len(merge)
    if L % 2: return float(merge[L//2])
    return (merge[L//2-1] + merge[L//2]) / 2

def search(nums, target):
    lo, hi = 0, len(nums)-1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target: return mid
        if nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]: hi = mid - 1
            else: lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]: lo = mid + 1
            else: hi = mid - 1
    return -1

from bisect import bisect_left
def search(nums, target):
    lo, hi = 0, len(nums)-1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]: lo = mid + 1
        else: hi = mid
    pivot = lo
    arr = nums[pivot:] + nums[:pivot]
    k = bisect_left(arr, target)
    if k < len(arr) and arr[k] == target:
        return (pivot + k) % len(nums)
    return -1

