def find_peak_element(nums):
    for i in range(len(nums)-1):
        if nums[i] > nums[i+1]: return i
    return len(nums)-1

def find_duplicate_set(nums):
    seen = set()
    for x in nums:
        if x in seen: return x
        seen.add(x)
    return -1

def is_perfect_square_newton(num):
    x = num
    while x * x > num:
        x = (x + num // x) // 2
    return x * x == num

def next_greatest_letter_scan(letters, target):
    for c in letters:
        if c > target:
            return c
    return letters[0]

def peak_index_linear(arr):
    i = 0
    while arr[i] < arr[i+1]:
        i += 1
